def findItinerary(tickets: list[list[str]]) -> list[str]:
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in sorted(tickets, reverse=True):
        graph[u].append(v)
    route = []
    def dfs(curr):
        while graph[curr]:
            nxt = graph[curr].pop()
            dfs(nxt)
        route.append(curr)
    dfs('JFK')
    return route[::-1]

